async function api(path: string, body?: unknown, method?: string) {
    const r = await fetch('/api' + path, { method: method || (body ? 'POST' : 'GET'), credentials: 'include', headers: body ? { 'Content-Type': 'application/json' } : undefined, body: body ? JSON.stringify(body) : undefined });
    let d: any;
    try {
        d = await r.json();
    }
    catch {
        throw new Error('The server could not complete this request. Please try again.');
    }
    if (!r.ok) {
        if (r.status === 401 && !['/auth/login', '/auth/me'].includes(path))
            window.dispatchEvent(new Event('campus-session-expired'));
        throw new Error(d.error || d.message || 'Unable to complete this request');
    }
    return d;
}
